cd /home/ubuntu/.agent-ml-research-idea_gen_0509_12/projects/simgate-modular-routing/docs/paper && python3 -c "
import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
lines = result.stdout.split('\n')
# Find page breaks (form feeds)
page = 1
for i, line in enumerate(lines):
    if '\x0c' in line:
        page += 1
    if 'Limitation' in line and page <= 6:
        print(f'Page {page}, line {i}: {line.strip()[:80]}')
    if 'Conclusion' in line and page <= 6:
        print(f'Page {page}, line {i}: {line.strip()[:80]}')
    if 'References' in line and page <= 6:
        print(f'Page {page}, line {i}: {line.strip()[:80]}')
    if 'Appendix' in line and page <= 6:
        print(f'Page {page}, line {i}: {line.strip()[:80]}')
print(f'Total pages: {page}')
"
